// ==========================================
// Root Component (Context Provider)
// ==========================================
/**
 * Core Location Root component that provides location context.
 * Parses location data and makes it available to all child components via context.
 * Tries to access LocationListService for label configuration.
 *
 * @component
 * @example
 * ```tsx
 * <CoreLocation.Root location={serviceLocation}>
 *   <Location.Name />
 *   <Location.Address />
 * </CoreLocation.Root>
 * ```
 */
export function Root(props) {
    const { location, children } = props;
    // Try to get LocationListService for labels - it's optional (Location can be standalone)
    let locationListService = null;
    try {
        // eslint-disable-next-line react-hooks/rules-of-hooks
        locationListService = useService(LocationListServiceDefinition);
    }
    catch {
        // LocationListService not available - using defaults
        locationListService = null;
    }
    // Get labels from service or use defaults
    const labels = {
        customLocationLabel: locationListService?.customLocationLabel.get(),
        customerLocationLabel: locationListService?.customerLocationLabel.get(),
    };
    const renderProps = computeLocationRenderProps(location, labels);
    return (_jsx(LocationContext.Provider, { value: renderProps, children: children }));
}
// ==========================================
// Data Component (Render Props)
// ==========================================
/**
 * Core Location Data component that exposes location data via render props.
 * Must be used within a CoreLocation.Root component.
 *
 * @component
 * @example
 * ```tsx
 * <CoreLocation.Root location={serviceLocation}>
 *   <CoreLocation.Data>
 *     {({ displayName, address }) => (
 *       <div>
 *         <span>{displayName}</span>
 *         {address && <Address.Formatted address={address} />}
 *       </div>
 *     )}
 *   </CoreLocation.Data>
 * </CoreLocation.Root>
 * ```
 */
export function Data(props) {
    const context = useLocationContext();
    return props.children(context);
}
/**
 * Core component that provides location selection actions via render props.
 * Sets the location in BookingService when select is called.
 *
 * @component
 * @example
 * ```tsx
 * <CoreLocation.Root location={location}>
 *   <CoreLocation.Actions>
 *     {({ select, selected, rawLocation }) => (
 *       <button onClick={select}>
 *         {selected ? 'Selected' : 'Select'}
 *       </button>
 *     )}
 *   </CoreLocation.Actions>
 * </CoreLocation.Root>
 * ```
 */
export function Actions(props) {
    const { rawLocation } = useLocationContext();
    // Try to get BookingService for setting location
    let bookingService = null;
    try {
        // eslint-disable-next-line react-hooks/rules-of-hooks
        bookingService = useService(BookingServiceDefinition);
    }
    catch {
        bookingService = null;
    }
    // Compute selected state from BookingService
    const selected = React.useMemo(() => {
        if (!bookingService || !rawLocation)
            return false;
        const currentLocation = bookingService.location.get();
        if (!currentLocation || !rawLocation)
            return false;
        // Compare by _id if available
        return currentLocation._id === rawLocation._id;
    }, [bookingService, rawLocation]);
    const select = () => {
        // Set location in BookingService
        if (bookingService && rawLocation) {
            bookingService.actions.setLocation(rawLocation);
        }
    };
    return props.children({
        select,
        rawLocation,
        selected,
    });
}
